PERFORM_WRITE(REG_LUTREG72, val);
			process_lut(s, val);
;			break;
		case REG_LUTREG73:
PERFORM_WRITE(REG_LUTREG73, val);
			process_lut(s, val);
;			break;
		case REG_LUTREG74:
PERFORM_WRITE(REG_LUTREG74, val);
			process_lut(s, val);
;			break;
