;			break;
		case REG_LUTREG77:
PERFORM_WRITE(REG_LUTREG77, val);
			process_lut(s, val);
;			break;

    default:
        printf("%s default action for write offset=%lx val=%lx size=%d\n", __func__, offset, val, size);
        s->regs[idx] = (uint32_t) val;
